import{_ as e,c as a,o,ag as n}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Matrix Bots and Add Ons","description":"","frontmatter":{"title":"Matrix Bots and Add Ons"},"headers":[],"relativePath":"matrix/matrix-bots-and-add-ons.md","filePath":"matrix/matrix-bots-and-add-ons.md","lastUpdated":null}'),r={name:"matrix/matrix-bots-and-add-ons.md"};function i(s,t,l,c,d,u){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="matrix-bots-and-add-ons" tabindex="-1">Matrix Bots and Add Ons <a class="header-anchor" href="#matrix-bots-and-add-ons" aria-label="Permalink to &quot;Matrix Bots and Add Ons&quot;">​</a></h1><h2 id="gpt-bot" tabindex="-1">GPT Bot <a class="header-anchor" href="#gpt-bot" aria-label="Permalink to &quot;GPT Bot&quot;">​</a></h2><p>This guide provides instructions for setting up a GPT-based bot within a Matrix environment, specifically using the configurations provided in the <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy" target="_blank" rel="noreferrer">matrix-docker-ansible-deploy</a> project.</p><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><ul><li>GPT Models: <a href="https://platform.openai.com/docs/models/gpt-4-and-gpt-4-turbo" target="_blank" rel="noreferrer">GPT-4 and GPT-4 Turbo Documentation</a></li><li>GPT API: <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">Obtain API Keys</a></li><li>GPT Pricing: <a href="https://openai.com/pricing" target="_blank" rel="noreferrer">Pricing Information</a></li></ul><h3 id="setting-up-a-bot-account-with-sso" tabindex="-1">Setting up a Bot Account with SSO <a class="header-anchor" href="#setting-up-a-bot-account-with-sso" aria-label="Permalink to &quot;Setting up a Bot Account with SSO&quot;">​</a></h3><p>Follow these steps to set up a bot account with Single Sign-On (SSO):</p><ol><li>Create an account using the SSO system.</li><li>Open a private browser window and log in to Matrix using the SSO credentials.</li><li>Set up recovery keys for the account.</li><li>Obtain the access token for the bot account: <ul><li>Navigate to <strong>All Settings</strong>.</li><li>Go to <strong>Help &amp; About</strong>.</li><li>Select <strong>Access Token</strong> to retrieve it.</li></ul></li><li>Ensure you DO NOT log out after retrieving the token.</li><li>Close the browser window to maintain the session.</li><li>Use the access token for configuring the bot account.</li></ol><p><strong>Note</strong>: When using SSO, disabling the local password option is necessary for SSO users to set up recovery keys.</p><h3 id="setting-up-an-account-with-access-token" tabindex="-1">Setting up an Account with Access Token <a class="header-anchor" href="#setting-up-an-account-with-access-token" aria-label="Permalink to &quot;Setting up an Account with Access Token&quot;">​</a></h3><p>For additional details on setting up an account using an access token, refer to the relevant GitHub discussion: <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/issues/2556" target="_blank" rel="noreferrer">Account Setup with Access Token</a></p><h3 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h3><p>For configuration details and further instructions, consult the documentation: <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/64db27c7faf3032341c665f8abf7aa66c7aa7aca/docs/configuring-playbook-bot-chatgpt.md" target="_blank" rel="noreferrer">Full Configuration Guide</a></p>',13)])])}const g=e(r,[["render",i]]);export{p as __pageData,g as default};
